zh:
// 手里一有分就收手。
function decide(s, p) {
  return s.see > 0 ? 0 : 1;
}

en:
// Stop as soon as there are any points in hand.
function decide(s, p) {
  return s.see > 0 ? 0 : 1;
}

zh:
// 累计不到 c 分就接着掷。
function decide(s, p) {
  return s.see >= p.c ? 0 : 1;
}

en:
// Keep rolling while the total is below c.
function decide(s, p) {
  return s.see >= p.c ? 0 : 1;
}

zh:
// 每回合都猜正面。
function decide(s, p) {
  return 1;
}

en:
// Guess heads every round.
function decide(s, p) {
  return 1;
}

zh:
// 上一次是正面就猜正面，否则猜反面。
function decide(s, p) {
  return s.see === 1 ? 1 : 0;
}

en:
// Guess heads if the previous flip was heads, otherwise tails.
function decide(s, p) {
  return s.see === 1 ? 1 : 0;
}

zh:
// 记下到现在出过几次正面，猜出得多的那一面（一样多时猜正面）。
function init(p) {
  return { heads: 0, n: 0 };
}
function decide(s, p, st) {
  if (s.t > 0) { st.n++; if (s.see === 1) st.heads++; }
  return 2 * st.heads >= st.n ? 1 : 0;
}

en:
// Keep count of the heads so far and guess the side that has come up more often (heads on a tie).
function init(p) {
  return { heads: 0, n: 0 };
}
function decide(s, p, st) {
  if (s.t > 0) { st.n++; if (s.see === 1) st.heads++; }
  return 2 * st.heads >= st.n ? 1 : 0;
}
